// src/lib/pdfFonts.ts
// Fontes embutidas (subconjunto Latim/pt-BR) para o gerador de PDF da lista de convidados.
// Poppins + Cormorant Garamond, subsetadas (~275KB). Importe este módulo de forma
// DINÂMICA (import("./pdfFonts")) dentro do gerador para não pesar o bundle inicial.
// Fontes: Google Fonts (OFL).
import type { jsPDF } from "jspdf";

const PoppinsLight =
  "";
const PoppinsRegular =
  "";
const PoppinsSemiBold =
  "";
const PoppinsLightItalic =
  "";
const Cormorant400 =
  "";
const Cormorant600 =
  "";
const CormorantItalic =
  "";

type Reg = jsPDF & {
  addFileToVFS: (f: string, d: string) => void;
  addFont: (f: string, family: string, style: string) => void;
};

let registered = false;

/**
 * Registra as fontes do PDF no documento jsPDF.
 * Idempotente por documento — chame uma vez logo após criar o `doc`.
 * Famílias resultantes:
 *   "Poppins"      -> normal (Regular), bold (SemiBold), italic (LightItalic)
 *   "PoppinsLight" -> normal (Light),   italic (LightItalic)
 *   "Cormorant"    -> normal (400),     bold (600),        italic (500 itálico)
 */
export function registerPdfFonts(doc: jsPDF): void {
  const d = doc as Reg;
  const add = (b64: string, file: string, family: string, style: string) => {
    d.addFileToVFS(file, b64);
    d.addFont(file, family, style);
  };
  add(PoppinsLight,       "PoppinsLight.ttf",       "PoppinsLight", "normal");
  add(PoppinsLightItalic, "PoppinsLightItalic.ttf", "PoppinsLight", "italic");
  add(PoppinsRegular,     "Poppins.ttf",            "Poppins",      "normal");
  add(PoppinsSemiBold,    "PoppinsSemiBold.ttf",    "Poppins",      "bold");
  add(PoppinsLightItalic, "PoppinsItalic.ttf",      "Poppins",      "italic");
  add(Cormorant400,       "Cormorant.ttf",          "Cormorant",    "normal");
  add(Cormorant600,       "CormorantSemi.ttf",      "Cormorant",    "bold");
  add(CormorantItalic,    "CormorantItalic.ttf",    "Cormorant",    "italic");
  registered = true;
}

export const PDF_FONT_REGISTERED = () => registered;
export const PDF_FONTS = {
  sans: "Poppins",
  sansLight: "PoppinsLight",
  serif: "Cormorant",
} as const;